local ButterChurner = {}
local PRODUCTS = {
    fresh_butter = { name = "Sveže maslo", milkCost = 3, saltCost = 1, time = 2, cost = 20, flavorStrength = 30, happiness = 2, description = "Sveže maslo za vsakdanjo rabo." },
    salted_butter = { name = "Slano maslo", milkCost = 4, saltCost = 2, time = 3, cost = 50, flavorStrength = 45, happiness = 3, prestige = 1, description = "Slano maslo za daljše shranjevanje." },
    cultured_butter = { name = "Kislo maslo", milkCost = 4, saltCost = 1, time = 5, cost = 110, flavorStrength = 60, happiness = 4, prestige = 3, description = "Kislo maslo z bogatim okusom." },
    herbed_butter = { name = "Zeliščno maslo", milkCost = 5, saltCost = 1, herbCost = 1, time = 7, cost = 240, flavorStrength = 75, happiness = 5, prestige = 6, description = "Zeliščno maslo za fine jedi." },
    silver_churned_butter = { name = "Srebrno stepeno maslo", milkCost = 6, saltCost = 1, silverCost = 1, herbCost = 1, time = 10, cost = 520, flavorStrength = 90, happiness = 7, prestige = 12, description = "Srebrno stepeno maslo za plemiče." },
    royal_grand_butter = { name = "Kraljevski veliki maslo", milkCost = 10, goldCost = 1, silverCost = 1, jewelCost = 1, saltCost = 2, herbCost = 2, time = 15, cost = 1400, flavorStrength = 100, happiness = 14, prestige = 35, description = "Veliko kraljevsko maslo z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Maslarska delavnica", cost = { gold = 270, wood = 130 }, upkeep = 6, qualityBonus = 5 },
    churn_house = { name = "Stepnica", cost = { gold = 850, wood = 250, stone = 350, milk = 10 }, upkeep = 20, qualityBonus = 18 },
    finishing_room = { name = "Dokončevalnica", cost = { gold = 2100, wood = 350, stone = 600, silver = 30, salt = 10 }, upkeep = 52, qualityBonus = 30 },
    royal_butter_atelier = { name = "Kraljevski atelje masla", cost = { gold = 8500, wood = 600, stone = 900, gold = 60, jewel = 20 }, upkeep = 170, qualityBonus = 55, prestigeBonus = 40 },
}
ButterChurner.milkStock = 22; ButterChurner.saltStock = 14; ButterChurner.herbStock = 12; ButterChurner.silverStock = 8; ButterChurner.goldStock = 6; ButterChurner.jewelStock = 6
ButterChurner.productStock = {}; ButterChurner.buildings = {}; ButterChurner.maker = nil; ButterChurner.activeMaking = {}; ButterChurner.totalProducts = 0; ButterChurner.dayTimer = 0
function ButterChurner.init() ButterChurner.milkStock=22; ButterChurner.saltStock=14; ButterChurner.herbStock=12; ButterChurner.silverStock=8; ButterChurner.goldStock=6; ButterChurner.jewelStock=6; ButterChurner.productStock={}; ButterChurner.buildings={}; ButterChurner.maker=nil; ButterChurner.activeMaking={}; ButterChurner.totalProducts=0; ButterChurner.dayTimer=0; print("[ButterChurner] Royal Butter Churner System initialized (6 products, 4 buildings)") end
function ButterChurner.hireMaker(n,s) s=s or math.random(50,90); local c=490+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; ButterChurner.maker={name=n or ("Maslar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Maslar najet: %s (spretnost: %d)",ButterChurner.maker.name,s),"success") end; return true end
function ButterChurner.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function ButterChurner.build(id) local ok,e=ButterChurner.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(ButterChurner.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function ButterChurner.getQualityBonus() local b=0; for _,bd in ipairs(ButterChurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function ButterChurner.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.milkCost and ButterChurner.milkStock<(d.milkCost or 0) then return false,"Premalo mleka" end; if d.saltCost and ButterChurner.saltStock<(d.saltCost or 0) then return false,"Premalo soli" end; if d.herbCost and ButterChurner.herbStock<(d.herbCost or 0) then return false,"Premalo zelišč" end; if d.silverCost and ButterChurner.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and ButterChurner.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and ButterChurner.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #ButterChurner.buildings==0 then return false,"Potrebna delavnica" end; if not ButterChurner.maker then return false,"Potreben maslar" end; return true end
function ButterChurner.make(pt,qty) qty=qty or 5; local ok,e=ButterChurner.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.milkCost then ButterChurner.milkStock=ButterChurner.milkStock-d.milkCost*qty end; if d.saltCost then ButterChurner.saltStock=ButterChurner.saltStock-d.saltCost*qty end; if d.herbCost then ButterChurner.herbStock=ButterChurner.herbStock-d.herbCost*qty end; if d.silverCost then ButterChurner.silverStock=ButterChurner.silverStock-d.silverCost*qty end; if d.goldCost then ButterChurner.goldStock=ButterChurner.goldStock-d.goldCost*qty end; if d.jewelCost then ButterChurner.jewelStock=ButterChurner.jewelStock-d.jewelCost*qty end; local t=d.time; if ButterChurner.maker then t=math.max(1,t-math.floor(ButterChurner.maker.skill/12)) end; table.insert(ButterChurner.activeMaking,{id="butter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function ButterChurner.completeMaking(m) local q=1.0+(ButterChurner.getQualityBonus()/100); if ButterChurner.maker then q=q+(ButterChurner.maker.skill/180) end; q=math.min(2.0,q); ButterChurner.productStock[m.productType]=(ButterChurner.productStock[m.productType] or 0)+m.quantity; ButterChurner.totalProducts=ButterChurner.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if ButterChurner.maker then ButterChurner.maker.itemsMade=ButterChurner.maker.itemsMade+m.quantity; if math.random()<0.20 then ButterChurner.maker.skill=math.min(100,ButterChurner.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Maslo izdelano: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"butter.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function ButterChurner.update(dt) if not _G.state then return end; ButterChurner.dayTimer=ButterChurner.dayTimer+dt; if ButterChurner.dayTimer>=30 then ButterChurner.dayTimer=0; for i=#ButterChurner.activeMaking,1,-1 do local m=ButterChurner.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then ButterChurner.completeMaking(m); table.remove(ButterChurner.activeMaking,i) end end; local tu=0; for _,bd in ipairs(ButterChurner.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if ButterChurner.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function ButterChurner.getStats() return {milkStock=ButterChurner.milkStock,saltStock=ButterChurner.saltStock,herbStock=ButterChurner.herbStock,silverStock=ButterChurner.silverStock,goldStock=ButterChurner.goldStock,jewelStock=ButterChurner.jewelStock,productStock=ButterChurner.productStock,numBuildings=#ButterChurner.buildings,hasMaker=ButterChurner.maker~=nil,makerName=ButterChurner.maker and ButterChurner.maker.name or "—",makerSkill=ButterChurner.maker and ButterChurner.maker.skill or 0,activeMaking=#ButterChurner.activeMaking,totalProducts=ButterChurner.totalProducts} end
return ButterChurner
